/* uglified */
let _azSoundHelper = null;
function _azHelperOnLoad() {
  window.addEventListener("load", async () => {
    try {
      var e = document.createElement("div"),
        n =
          ((e.id = "_azExtraContainer"),
          e.setAttribute("tabindex", "0"),
          (e.style.height = "100vh"),
          (e.style.width = "100vw"),
          (e.style.display = "none"),
          (e.style.position = "absolute"),
          (e.style.top = "0"),
          (e.style.left = "0"),
          (e.style.backgroundColor = "rgba(0, 0, 0, 0.9)"),
          (e.style.zIndex = 999),
          document.body.appendChild(e),
          document.createElement("p"));
      (n.innerText = "Click to Resume"),
        (n.style.position = "absolute"),
        (n.style.top = "50%"),
        (n.style.left = "50%"),
        (n.style.transform = "translate(-50%, -50%)"),
        (n.style.margin = "0"),
        (n.style.fontSize = "40px"),
        (n.style.fontFamily = "Aquino-Demo"),
        (n.style.color = "white"),
        (n.style.textAlign = "center"),
        e.appendChild(n);
      let t = document.getElementById("_azExtraContainer");
      t.addEventListener("click", async (e) => {
        _azerionIntegrationSDK.isAdPlaying() ||
          (e.stopPropagation(),
          e.preventDefault(),
          t.focus(),
          await _triggerSoundFix(),
          (e = document.getElementById("_azExtraContainer")) &&
            (e.style.display = "none"),
          console.log("Canvas manually focused on click"));
      });
    } catch (e) {
      console.log("[az c3 extra] Error in load event listener", e);
    }
    window.addEventListener("blur", () => {
      _azShowResumeText();
      _azSoundHelper?.stop();
    }),
      setTimeout(() => {}, 1e4);
  });
}
async function _triggerSoundFix() {
  _azSoundHelper?.stop();
  if (_azSoundHelper === null) {
    _azSoundHelper = await _createSound({
      src: "sounds/button_click.mp3?",
      volume: 1,
      html5: false,
    });
  }
  _azSoundHelper.play();
  setTimeout(() => {
    Howler.ctx.resume().then(() => {
      console.log("Audio context resumed");
      (t = new CustomEvent("ApplicationResumed", {
        detail: { message: "Resume text displayed" },
      })),
        window.dispatchEvent(t);
    });
  }, 1e4);
}
function _createSound(option) {
  const _azSoundHelper = new Howl(option);
  return new Promise((resolve, reject) => {
    _azSoundHelper.once("load", () => {
      resolve(_azSoundHelper);
    });
    _azSoundHelper.once("loaderror", () => {
      reject();
    });
  });
}
function _azExtraAdListener() {
  try {
    var e = navigator.userAgent,
      t = /iPhone/i.test(e),
      n = e.match(/OS (\d+)_\d+/),
      a = n ? parseInt(n[1], 10) : 0;
    t &&
      document.getElementById("_azExtraContainer") &&
      _azerionIntegrationSDK.ads.azAdWrapper.on(
        h5ads.AdEvents.CONTENT_RESUMED,
        () => {
          var e = document.getElementById("_azExtraContainer");
          console.log("--_azExtraAdListener -- CONTENT_RESUMED"),
            e &&
              ((e.style.height = "100vh"),
              (e.style.width = "100vw"),
              (e.style.display = "block"));
        }
      );
  } catch (e) {
    console.log("[az c3 extra] Error in blur event listener", e);
  }
}
function _azShowResumeText() {
  try {
    var e,
      t,
      n = navigator.userAgent,
      a = /iPhone/i.test(n),
      o = n.match(/OS (\d+)_\d+/),
      l = o ? parseInt(o[1], 10) : 0;
    a &&
      (e = document.getElementById("_azExtraContainer")) &&
      ((e.style.height = "100vh"),
      (e.style.width = "100vw"),
      (e.style.display = "block"),
      (t = new CustomEvent("ApplicationPaused", {
        detail: { message: "Resume text displayed" },
      })),
      window.dispatchEvent(t));
  } catch (e) {
    console.log("[az c3 extra] Error in blur event listener", e);
  }
}
_azHelperOnLoad();
